# --- Full happy-path cycle: start -> upload x7 -> submit -> verdict x7 -> approve ---


def test_full_cycle_leaves_exactly_one_row_in_each_downstream_table(
    session, svc, model, rm, compliance
):
    dto = run_full_approved_cycle(
        svc, model, rm_uid=rm.firebase_uid, compliance_uid=compliance.firebase_uid
    )

    assert dto.status == "active"
    subs = session.query(ClientSubscription).filter_by(user_id=dto.user_id).all()
    assert len(subs) == 1
    assert subs[0].multiplier == Decimal("5")

    allotments = svc.list_allotments()
    assert len(allotments) == 1
    assert allotments[0].status == "pending"
    assert allotments[0].note == "initial allotment"

    user_row = session.get(User, dto.user_id)
    assert user_row.status == AccountStatus.ACTIVE

    events = svc.client_events(dto.user_id)
    assert len(events) == 1


