# --- agg_before / agg_after ordering invariant (C-2/C-7, widened 2026-07-20) --------


def test_agg_before_excludes_this_clients_own_new_row_not_double_counted(
    session, svc, model, rm, compliance
):
    """Seed two other clients already subscribed (10 + 15 = 25), then approve
    a third client's units=5 initial cycle -- agg_before must be 25 (the
    PRE-existing sum), not 30 (which would mean this client's own row was
    read back into its own agg_before)."""
    repo = OnboardingRepository(session)
    client_a = make_client(session)
    client_b = make_client(session)
    repo.upsert_subscription(
        user_id=client_a.id,
        model_id=model.id,
        multiplier=Decimal("10"),
        mgmt_fee_override=None,
        incentive_fee_override=None,
    )
    repo.upsert_subscription(
        user_id=client_b.id,
        model_id=model.id,
        multiplier=Decimal("15"),
        mgmt_fee_override=None,
        incentive_fee_override=None,
    )
    session.commit()

    run_full_approved_cycle(
        svc,
        model,
        rm_uid=rm.firebase_uid,
        compliance_uid=compliance.firebase_uid,
        units=Decimal("5"),
    )
    allotment = svc.list_allotments()[0]
    assert allotment.agg_before == Decimal("25")
    assert allotment.agg_after == Decimal("30")


