def test_expected_cash_in_honours_settlement_days_env_override(
    monkeypatch, svc, model, rm, compliance
):
    """Monkeypatches the module-level constant directly (the doc's own §8.3
    alternative to reload+setenv) -- `_approve_initial` reads
    ONBOARDING_SETTLEMENT_DAYS from the module namespace at call time, so this
    exercises the real code path without reload's side effect of rebinding
    `get_storage` back to the real (filesystem-touching) implementation."""
    import app.libs.onboarding.service as service_module

    monkeypatch.setattr(service_module, "ONBOARDING_SETTLEMENT_DAYS", 10)
    run_full_approved_cycle(
        svc, model, rm_uid=rm.firebase_uid, compliance_uid=compliance.firebase_uid
    )
    allotment = svc.list_allotments()[0]
    delta = allotment.expected_cash_in - allotment.created_at
    assert abs(delta - timedelta(days=10)) < timedelta(seconds=5)


def test_settlement_days_env_var_never_goes_negative(monkeypatch):
    """`max(0, int(...))` guard -- a negative override cannot produce a
    settlement date in the past relative to created_at by construction."""
    monkeypatch.setenv("ONBOARDING_SETTLEMENT_DAYS", "-5")
    import importlib

    import app.libs.onboarding.service as service_module

    importlib.reload(service_module)
    try:
        assert service_module.ONBOARDING_SETTLEMENT_DAYS == 0
    finally:
        monkeypatch.delenv("ONBOARDING_SETTLEMENT_DAYS", raising=False)
        importlib.reload(service_module)


