# --- Invariant: duplicate allotment DB guarantee, independent of the kind branch -----


def test_direct_duplicate_source_onboarding_id_at_repo_layer_raises_integrity_error(
    session, svc, model, rm, compliance
):
    from sqlalchemy.exc import IntegrityError

    dto = run_full_approved_cycle(
        svc, model, rm_uid=rm.firebase_uid, compliance_uid=compliance.firebase_uid
    )
    with pytest.raises(IntegrityError):
        svc.repo.create_allotment(
            user_id=dto.user_id,
            model_id=model.id,
            multiplier=Decimal("1"),
            source_onboarding_id=dto.id,
            agg_before=Decimal("5"),
            agg_after=Decimal("6"),
            expected_cash_in=datetime.utcnow(),
        )
        session.commit()
    session.rollback()


# --- Invariant: a failed approve rolls back totally, not partially ------------------


def test_failed_approve_leaves_all_downstream_tables_unchanged(
    monkeypatch, session, svc, model, rm, compliance
):
    submitted = run_to_reviewing(svc, model, rm_uid=rm.firebase_uid)
    svc.verdict_batch(
        submitted.id,
        VerdictBatchReq(
            items=[VerdictItem(doc_type=spec.key, verdict="valid") for spec in REQUIRED_DOCS]
        ),
        reviewer_uid=compliance.firebase_uid,
    )

    def _boom(*args, **kwargs):
        raise RuntimeError("simulated failure mid-approve")

    monkeypatch.setattr(svc.repo, "create_allotment", _boom)

    before_subs = session.query(ClientSubscription).count()
    before_allotments = len(svc.list_allotments())
    before_events = len(svc.client_events(submitted.user_id))
    before_user = session.get(User, submitted.user_id)
    before_status = before_user.status

    with pytest.raises(RuntimeError):
        svc.approve(submitted.id, compliance_uid=compliance.firebase_uid)

    assert session.query(ClientSubscription).count() == before_subs
    assert len(svc.list_allotments()) == before_allotments
    assert len(svc.client_events(submitted.user_id)) == before_events
    after_user = session.get(User, submitted.user_id)
    assert after_user.status == before_status

    onboarding = session.get(ClientOnboarding, submitted.id)
    assert onboarding.status == "reviewing"  # never flipped to active


